  "fake-data-generator": ["Check the fields you want and set the number of rows to generate.","Choose an output format (JSON, CSV, or SQL) and optionally enter a seed for reproducible data.","Click Copy or Download to save the generated data."],
  "ascii-banner": ["Type or paste your text into the banner text box.","Choose a fill character and letter spacing to style the letters.","Click Copy banner or Download .txt to save your ASCII art."],
  "portfolio-rebalance-calculator": ["Add each holding with its current dollar value and the target percentage you want it to be.","Optionally enter new cash to invest so the plan buys underweight assets instead of selling.","Read the buy or sell amount for each holding, then copy the plan to act on it."],
  "css-formatter": ["Paste your CSS into the input box.","Choose Beautify with an indentation style, or choose Minify to compress.","Copy the formatted result or download it as a .css file."],
  "svg-optimizer": ["Paste your SVG code into the box, or upload an .svg file.","Choose which optimizations to apply and set the number precision.","Check the preview and savings, then copy or download the optimized SVG."],
  "json-schema-generator": ["Paste a sample JSON object or array into the input box.","Pick a schema draft and toggle required, additionalProperties, and examples options.","Copy the generated JSON Schema or download it as schema.json."],
  "word-frequency-counter": ["Paste or type your text into the box.","Adjust case handling, stop-word skipping, and minimum word length if you want.","Read the ranked word list, then copy it or download the full results as CSV."],
  "px-to-rem-converter": ["Set the root font size (base) in pixels, or leave it at the default 16.","Type a pixel value to get rem, or type a rem value to get pixels.","Copy the result, or use the reference table for common sizes."],
  "unicode-lookup": ["Choose a mode: inspect text, or find a character by code point.","Paste your text, or type a code point like U+1F600 or 128512.","Read the code point, block, category, and encodings, and copy any value you need."],
  "bitwise-calculator": ["Enter operand A, and operand B if the operation needs two inputs, choosing a base for each.","Pick the operation (AND, OR, XOR, NOT, shift, and so on) and the bit width that matches your data.","Read the result in binary, hex, decimal, and octal, and check the bit-by-bit breakdown to see how it lines up."],
  "user-agent-parser": ["Paste a User-Agent string into the box, or click \"Use my browser\" to load your own.","Read the browser, engine, OS and device breakdown shown below the input.","Click \"Copy JSON\" to grab the parsed result for your code or notes."],
  "pdf-metadata-editor": ["Choose a PDF file to load its current metadata into the form.","Edit the title, author, subject, keywords, creator, producer or dates as needed.","Click Apply and download to save the PDF with your updated metadata."],
  "image-steganography": ["Choose Hide mode, pick a cover image, and type the secret text you want to conceal.","Optionally add a passphrase, then click Hide & Create PNG and download the identical-looking PNG.","To read it back, switch to Reveal mode, load that PNG, enter the passphrase if any, and click Reveal Message."],
  "burn-rate-calculator": ["Enter your current cash on hand and choose your currency.","Enter your total monthly expenses (cash out) and your monthly revenue (cash in).","Read your gross burn, net burn, runway in months, and estimated cash-out date."],
  "jsonpath-tester": ["Paste or type your JSON into the JSON box (an example is loaded so you can start immediately).","Enter a JSONPath expression, such as $..book[?(@.price < 10)].title, or click an example query.","Read the matched values and their exact paths in the result panel, and copy the values with one click."],
  "password-strength-checker": ["Type or paste the password you want to test into the input field.","Read the strength rating, entropy, and estimated crack times shown below.","Apply the specific suggestions to make the password longer and less predictable."],
  "readability-checker": ["Paste or type your text into the box.","Read your Flesch Reading Ease score and the average grade level shown below it.","Simplify long sentences and complex words, then recheck until you hit your target level."],
  "color-blindness-simulator": ["Upload an image, or use the built-in color test pattern that loads automatically.","Pick a type of color blindness from the dropdown to simulate it.","Compare the original and simulated views, then download the result as a PNG."],
  "pdf-to-markdown": ["Choose a text-based PDF file using the file picker.","Adjust the heading, list, page-separator, and line-break options if needed.","Copy the Markdown or download it as a .md file."],
  "bates-numbering": ["Choose one or more PDF files to number.","Set the prefix, starting number, digits, and stamp position.","Click Apply Bates numbers and download the stamped PDF."],
  "remove-line-breaks": ["Paste or type your text into the input box.","Pick what should replace each line break and toggle the paragraph, empty-line, and spacing options.","Click Copy result to grab the cleaned text."],
  "image-to-ascii": ["Drop an image onto the box or click to browse and select a file from your device.","Adjust the width, character set, contrast, brightness, and invert until the art reads clearly.","Copy the text or download it as a .txt or .png file."],
  "tiff-to-png": ["Drag a .tif or .tiff file onto the box, or click to choose one from your device.","Wait a moment while the TIFF is decoded and rendered as a PNG preview; for multi-page files, pick a page from the dropdown.","Click Download PNG to save the current page, or Download all pages to get every page as a ZIP."],
  "csv-viewer": ["Open a CSV file or paste your CSV text into the box.","Set the delimiter (or leave it on auto-detect) and toggle whether the first row is a header.","Click a column heading to sort, or type in the search box to filter rows."],
