  "javascript-formatter": ["Paste your minified or messy JavaScript into the input box.","Choose your indent size - 2 spaces, 4 spaces, or tabs.","Copy or download the beautified code, or click Minify instead to compact it."],
  "fill-pdf-form": ["Choose a fillable PDF form from your device.","Type into the text fields and set any checkboxes, dropdowns, or options.","Optionally flatten it, then click Fill and download your completed PDF."],
  "markdown-table-generator": ["Type your headers and data into the grid, adding columns and rows as needed, or click Paste data to import from a spreadsheet.","Set each column's alignment (left, center, right, or default) using the dropdown under its header.","Click Copy Markdown and paste the table into GitHub, Obsidian, or any Markdown editor."],
  "black-scholes-calculator": ["Choose call or put, then enter the spot price, strike price, and days to expiration.","Enter the annual volatility, the risk-free interest rate, and any dividend yield.","Read the theoretical option price and the delta, gamma, vega, theta, and rho below."],
  "position-size-calculator": ["Enter your account balance and set how much to risk on the trade, either as a percentage of your account or a fixed amount.","Type in your planned entry price and your stop-loss price.","Read your position size and round it down to a whole number of shares or lots before placing the trade."],
  "json-escape": ["Choose Escape to convert raw text into a JSON string, or Unescape to convert a JSON string back to text.","Type or paste your text into the input box and adjust the options if you need quotes or \\u encoding.","Copy the result from the output area to use in your code or config file."],
  "kelly-criterion-calculator": ["Enter your estimated win probability as a percentage and the net odds you receive on a win.","Type in your total bankroll and choose a Kelly fraction (Full, Half, or Quarter).","Read the suggested stake percentage and dollar amount, and use a smaller fraction if you want less volatility."],
  "browser-fingerprint": ["Open the page and let it read your browser signals automatically.","Review your fingerprint ID and the full list of collected signals below it.","Reload or open a different browser to see whether the ID stays the same, then copy the full report if you want to save it."],
  "cash-flow-calculator": ["Enter your starting cash balance and how many months to project.","Add your monthly income sources and expenses, each with an amount.","Read your net cash flow, projected balance, and cash runway below."],
  "file-encryptor": ["Choose Encrypt mode, pick any file, and enter a strong password twice.","Click Encrypt & download to save the password-locked .ebtenc file.","To restore it, switch to Decrypt mode, choose the .ebtenc file, enter the same password, and download the original."],
  "bmp-to-png": ["Drag your BMP file onto the drop zone, or click to choose one or more .bmp files.","Wait a moment while each image is decoded and re-encoded as a lossless PNG in your browser.","Click Download PNG for a single file, or Download all to save every converted image."],
  "box-shadow-generator": ["Drag the offset, blur, spread, and opacity sliders and pick a shadow color until the preview looks right.","Click Add shadow to stack extra layers for more realistic depth, editing each layer separately.","Click Copy CSS to copy the box-shadow rule and paste it into your stylesheet."],
  "forex-pip-calculator": ["Enter the base, quote and account currencies as 3-letter codes, then choose a lot size and number of lots.","Type the current price of the pair, and a quote-to-account conversion rate if your account currency differs from both sides.","Read the pip value shown in your account currency, along with the quote-currency value and the value of 10 pips."],
  "bond-ytm-calculator": ["Enter the bond's face value, current market price, annual coupon rate, and years remaining to maturity.","Select how many coupon payments the bond makes per year (semi-annual is typical).","Read the annual yield to maturity, plus effective annual yield and current yield, which update instantly."],
  "resize-pdf": ["Choose your PDF file — it loads and stays entirely in your browser.","Pick a target page size and orientation.","Click Resize PDF and download the result."],
  "stock-average-calculator": ["Enter the number of shares and the price per share for your first purchase.","Click Add another buy and fill in the shares and price for each additional purchase at a different price.","Read your average cost per share, and optionally enter the current price to see your gain or loss."],
  "circle-crop": ["Upload an image and use the zoom and position sliders to frame your subject inside the circle.","Pick an output size and background, and optionally add a border ring.","Click Crop & Download PNG to save your circular image."],
  "random-string-generator": ["Set the length and how many strings you want, then choose which character sets to include.","Optionally exclude look-alike characters, require one from each set, or paste a custom character set.","Click Generate, then copy a single string, copy all, or download them as a .txt file."],
  "binary-text-converter": ["Choose a direction: Binary to text, or Text to binary.","Paste your binary or type your text into the input box.","Read or copy the converted result shown below."],
  "crypto-profit-calculator": ["Choose whether to enter dollars invested or a quantity of coins, then type that amount.","Enter your buy price and sell price per coin, plus your buy and sell fee percentages.","Read your net profit, ROI, multiple, total fees, and break-even sell price instantly."],
  "redact-pdf": ["Choose your PDF file to load and preview its pages in the browser.","Drag black boxes over every name, number, or line of text you want to hide, using Prev/Next for multi-page files.","Click Apply & build redacted PDF, then download the flattened copy with the text permanently removed."],
  "ltv-calculator": ["Choose your business model — subscription (churn-based) or transactional (order-based) — and select a currency.","Enter your revenue, retention figures, and gross margin; optionally add your acquisition cost per customer.","Read the customer lifetime value, gross revenue LTV, and LTV:CAC ratio that update instantly below."],
  "sitemap-generator": ["Paste your page URLs into the box, one full URL per line.","Optionally set a change frequency, priority, and last-modified date for all URLs.","Copy the XML or download sitemap.xml and upload it to your site's root."],
